 $('#canvas').innerHTML=`<svg width="${width}" height="${height}" aria-hidden="true"></svg>${board.sample?`<div class="lane-label" style="left:30px;top:55px">01 / YOUR FACTS</div><div class="lane-label" style="left:340px;top:55px">02 / THE RULES & THEIR SOURCES</div><div class="lane-label" style="left:1100px;top:55px">03 / WHAT FOLLOWS</div>`:''}${nodes.map(n=>card(n)).join('')}${!nodes.length?'<div class="empty"><h2>Start with a question.<br>Build from the evidence.</h2><p>Add a fact, a claim, or a source using the authoring toolbar.</p>'+(readerMode?'':'<div class="empty-actions"><button class="dark" data-open-outline>✎ Start jotting</button><button data-guide="tour">▶ Take the guided tour</button><button data-guide="primer">How this works</button><button data-guide="author">Start authoring</button></div>')+'</div>':''}`;
