function openConnection(id,linkId=null){const l=linkId&&board.links.find(l=>l.id===linkId),n=get(id);editingId=linkId;const opts=board.nodes.map(n=>[n.id,n.type+': '+wording(n).slice(0,85)]);showEditor(l?'Edit connection':'Connect two cards',`<label class="form-label" for="link-from">From</label><select id="link-from">${options(opts,l?.from||id)}</select><label class="form-label" for="link-kind">Relationship</label><select id="link-kind">${options([['reasoning','is a reason for'],['supports','is a source for'],['challenges','pushes back on'],['questions','raises a question about']],l?.kind||(n?.type==='evidence'?'supports':'reasoning'))}</select><label class="form-label" for="link-to">To</label><select id="link-to">${options(opts,l?.to||board.nodes.find(n=>n.id!==id)?.id)}</select>`+input('link-label','Why are these connected?',l?.label||'')+'<p class="form-help">Connections are authored by you. “Supports” does not verify a claim. Contradictions stay visible until you edit or remove the connection.</p>','connection');$('#link-from').onchange=syncLinkKinds;syncLinkKinds()}
