function brief(){const lines=['# '+board.title,board.subtitle||'','Authored evidence map. Connections express the author’s reasoning; they do not independently verify claims.',''];for(const [i,n] of sequence().entries()){lines.push(`## ${i+1}. ${wording(n)}`,`Type: ${n.type}`,n.note||'');const related=board.links.filter(l=>l.to===n.id||l.from===n.id);if(n.type==='evidence')lines.push(n.quote?'Passage: '+n.quote:'',deepLink(n));for(const l of related){const other=get(l.from===n.id?l.to:l.from);if(!other)continue;lines.push(`${l.from===n.id?'Outgoing':'Incoming'} ${l.kind}${l.label?' ('+l.label+')':''}: ${wording(other)}`);if(other.type==='evidence')lines.push(other.quote?'Passage: '+other.quote:'',`Source: ${deepLink(other)}`,`Authority (author-assigned): ${other.tier||'Unreviewed'}; checked: ${other.checked||'not recorded'}`,other.image?'Screenshot and highlights included in the companion board file.':'')}lines.push('')}lines.push('## Other cards',...board.nodes.filter(n=>active(n)&&!sequence().some(s=>s.id===n.id)&&n.type!=='evidence').map(n=>`- [${n.type}] ${wording(n)}`),'','## Source register',...board.nodes.filter(n=>n.type==='evidence'&&active(n)).map(n=>`- ${n.text}: ${deepLink(n)} (checked ${n.checked||'not recorded'})`));return lines.filter(l=>l!==undefined).join('\n')}
$('#share').onclick=()=>{$('#brief-text').value=brief();$('#brief-dialog').showModal()};
