document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,select,[contenteditable]')&&!$('dialog[open]')){e.preventDefault();undo(e.shiftKey)}if(e.target.matches('#canvas [data-node]')&&author&&!readerMode&&!walking&&!$('dialog[open]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=get(e.target.dataset.node),amount=e.shiftKey?50:10;delete n.auto;n.x=Math.max(0,n.x+(e.key==='ArrowLeft'?-amount:e.key==='ArrowRight'?amount:0));n.y=Math.max(0,n.y+(e.key==='ArrowUp'?-amount:e.key==='ArrowDown'?amount:0));persist();render();$(`#canvas [data-node="${CSS.escape(n.id)}"]`)?.focus()}});
