async function initializeWorkspaceUI(){
  window.history.replaceState(null,'','?'+new URLSearchParams({...Object.fromEntries(new URLSearchParams(location.search)),j:session.journey.id,b:session.record.id}));
  $('.brand').href='../journey/journey.html?j='+encodeURIComponent(session.journey.id);
  $('.brand').innerHTML='<span class="brandmark">▧</span> THE THINGS WE LEARNED';
  $('.brand').setAttribute('aria-label','Return to browsing trail');
  $('.topline').insertAdjacentHTML('afterend','<nav class="workspace-nav"><a id="trail-link">Browsing trail</a><span aria-current="page">Evidence board</span><label for="board-picker">Argument</label><select id="board-picker"></select><button id="inbox-button">Evidence inbox</button></nav>');
  $('#trail-link').href='../journey/journey.html?j='+encodeURIComponent(session.journey.id);
  refreshPicker();
  $('#board-picker').onchange=async e=>{const id=e.target.value;await saveQueue;if(saveBlocked){e.target.value=session.record.id;notify('Save your board file and reload before switching arguments.');return;}location.href='?'+new URLSearchParams({j:session.journey.id,b:id});};
  $('#inbox-button').onclick=()=>showInbox();
  $('#save-status').textContent='Saved in '+session.journey.name;
  globalThis.chrome?.runtime?.onMessage?.addListener(msg=>{if(msg.type==='trail-updated'&&msg.journeyId===session.journey.id)$('#inbox-button').textContent='Evidence inbox · updated';});
}
function refreshPicker(){if(!$('#board-picker'))return;$('#board-picker').innerHTML=session.boards.map(b=>`<option value="${esc(b.id)}" ${b.id===session.record.id?'selected':''}>${esc((t=>t==='What am I trying to establish?'?'Untitled question':t)(b.id===session.record.id?board.title:b.content.title))}</option>`).join('');}
async function showInbox(){
  let dialog=$('#inbox-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='inbox-dialog';document.body.append(dialog);}
  dialog.innerHTML='<div class="dialog-heading"><h2>Evidence inbox</h2><button data-close aria-label="Close evidence inbox">✕</button></div><p>Loading captured passages…</p>';dialog.showModal();
  try{
    const captures=await workspace.inbox(session.journey.id);
    dialog.innerHTML=`<div class="dialog-heading"><h2>Evidence inbox</h2><button data-close aria-label="Close evidence inbox">✕</button></div><p class="form-help">Select text on a page and right-click → Add passage to evidence board. Use Capture screenshot as evidence for a visible-page snapshot. Existing highlights are also available here.</p><label class="form-label" for="inbox-target">Attach new evidence to a claim (optional)</label><select id="inbox-target"><option value="">Add without a connection</option>${board.nodes.filter(n=>['claim','conclusion','gap'].includes(n.type)).map(n=>`<option value="${esc(n.id)}" ${selected===n.id?'selected':''}>${esc(n.text)}</option>`).join('')}</select><div class="inbox-items">${captures.map(c=>`<article class="inbox-item"><p class="eyebrow">${esc(domain(c.url))} · ${esc(c.view||'original')}</p><h3>${esc(c.title)}</h3>${c.quote?`<blockquote>${esc(c.quote)}</blockquote>`:''}${c.note?`<p class="form-help">${esc(c.note)}</p>`:''}<p class="form-help">${esc(new Date(c.capturedAt).toLocaleString())}${c.image?' · Screenshot included':''}</p><button data-pin-capture="${esc(c.id)}" ${board.nodes.some(n=>n.sourceCaptureId===c.id)?'disabled':''}>${board.nodes.some(n=>n.sourceCaptureId===c.id)?'Already on this board':c.kind==='note'?'Add as a thought':'Add & edit evidence'}</button></article>`).join('')||'<p class="empty">No captured evidence yet. You can also add evidence manually from the Author toolbar.</p>'}</div>`;
    dialog.querySelectorAll('[data-pin-capture]').forEach(button=>button.onclick=()=>{
      if(board.nodes.length>=500){notify('This board has reached the 500-card limit.');return;}
      const capture=captures.find(c=>c.id===button.dataset.pinCapture);if(!capture)return;
      const card=capture.kind==='note'?workspace.noteCard(capture,freePosition()):workspace.evidenceCard(capture,freePosition());board.nodes.push(card);
      const target=$('#inbox-target').value;if(target)board.links.push({id:uid(),from:card.id,to:target,kind:get(target)?.type==='gap'?'questions':'supports',label:''});
      selected=card.id;author=true;persist();dialog.close();render();if(card.type==='evidence')openCard('evidence',card.id);
    });
    $('#inbox-button').textContent='Evidence inbox';
  }catch(error){dialog.querySelector('p').textContent=error.message;}
}
